import React, { useEffect, useState } from "react";
import "../styles/Sidebar.css";
import { NavLink, useNavigate } from "react-router-dom";

const Sidebar = () => {
  const [user, setUser] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    // Read user from localStorage (set during login)
    const stored = localStorage.getItem("user");
    if (stored) {
      try { setUser(JSON.parse(stored)); } catch { setUser(null); }
    }
    // Uncomment when API is ready:
    // fetch("https://api.example.com/user/me", {
    //   headers: { Authorization: `Bearer ${localStorage.getItem("authToken")}` }
    // })
    //   .then((res) => res.json())
    //   .then((data) => setUser(data))
    //   .catch(() => setUser(null));
  }, []);

  const handleLogout = () => {
    localStorage.removeItem("authToken");
    localStorage.removeItem("user");
    setUser(null);
    navigate("/login");
  };

  const isGuest = !user;

  return (
    <aside className="sidebar">

      {/* ── Header ─────────────────────────────────────────────── */}
      <div className="sidebar-header">
        <div className="sidebar-logo">🏛️</div>
        <h2 className="portal-title">Gram Panchayat</h2>
        <h3 className="portal-subtitle">Digital Seva Portal</h3>
        <div className="user-box">
          <div className="user-avatar">
            {user?.name ? user.name.charAt(0).toUpperCase() : "G"}
          </div>
          <span className="user-name">{user?.name || "Guest User"}</span>
        </div>
      </div>

      {/* ── Nav ────────────────────────────────────────────────── */}
      <nav className="sidebar-nav">
        <ul>

          <li>
            <NavLink to="/home">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <path d="M3 9l9-7 9 7v11a2 2 0 01-2 2H5a2 2 0 01-2-2z"/>
                <polyline points="9 22 9 12 15 12 15 22"/>
              </svg>
              Home
            </NavLink>
          </li>

          
          <li>
            <NavLink to="/" end>
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <polygon points="1 6 1 22 8 18 16 22 23 18 23 2 16 6 8 2 1 6"/>
                <line x1="8" y1="2" x2="8" y2="18"/>
                <line x1="16" y1="6" x2="16" y2="22"/>
              </svg>
              Map
            </NavLink>
          </li>

          {/* Only show for logged-in users */}
          {!isGuest && (
            <li>
              <NavLink to="/complaints">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/>
                  <polyline points="14 2 14 8 20 8"/>
                  <line x1="16" y1="13" x2="8" y2="13"/>
                  <line x1="16" y1="17" x2="8" y2="17"/>
                </svg>
                My Complaints
              </NavLink>
            </li>
          )}

          {!isGuest && (
            <li>
              <NavLink to="/profile">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <path d="M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2"/>
                  <circle cx="12" cy="7" r="4"/>
                </svg>
                Profile
              </NavLink>
            </li>
          )}

          <li>
            <NavLink to="/support">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <circle cx="12" cy="12" r="10"/>
                <path d="M9.09 9a3 3 0 015.83 1c0 2-3 3-3 3"/>
                <line x1="12" y1="17" x2="12.01" y2="17"/>
              </svg>
              Help &amp; Support
            </NavLink>
          </li>

          <li>
            <NavLink to="/about">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <circle cx="12" cy="12" r="10"/>
                <line x1="12" y1="8" x2="12" y2="12"/>
                <line x1="12" y1="16" x2="12.01" y2="16"/>
              </svg>
              About
            </NavLink>
          </li>

        </ul>
      </nav>

      {/* ── Footer ─────────────────────────────────────────────── */}
      <div className="sidebar-footer">
        {isGuest ? (
          <NavLink to="/login" className="sidebar-login-btn">
            Login / Register
          </NavLink>
        ) : (
          <button className="sidebar-logout-btn" onClick={handleLogout}>
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M9 21H5a2 2 0 01-2-2V5a2 2 0 012-2h4"/>
              <polyline points="16 17 21 12 16 7"/>
              <line x1="21" y1="12" x2="9" y2="12"/>
            </svg>
            Logout
          </button>
        )}
        <p className="sidebar-powered">Powered by <strong>Digital India</strong></p>
      </div>

    </aside>
  );
};

export default Sidebar;
